/** Single source of truth for the brand name and environment-driven settings. */
export const BRAND = { nameEn: "Little Learners BD", nameBn: "লিটল লার্নার্স বিডি", short: "Little Learners" } as const;

/** Base URL of the R2 custom domain. Empty => serve from /dev-assets (generated by `npm run assets`). */
export const ASSET_BASE: string = (import.meta.env.VITE_ASSET_BASE_URL ?? "").replace(/\/$/, "");
export const DEV_ASSET_PATH = "/dev-assets";
export const CONTENT_PATH = "/content";
